def check_func(final_state):
    from datetime import datetime

    def parse_due_date(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.strptime(s, "%Y-%m-%d").date()
        except Exception:
            return None

    def parse_returned_datetime(s):
        if not isinstance(s, str):
            return None
        # Try ISO and common formats
        try:
            s2 = s.replace("Z", "+00:00")
            if "T" not in s2 and len(s2) == 10:
                return datetime.strptime(s2, "%Y-%m-%d")
            return datetime.fromisoformat(s2)
        except Exception:
            fmts = ["%Y-%m-%d %H:%M:%S", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d"]
            for f in fmts:
                try:
                    return datetime.strptime(s, f)
                except Exception:
                    continue
        return None

    def str_contains_overdue(s):
        if not isinstance(s, str):
            return False
        ls = s.lower()
        return ("overdue" in ls) or ("late" in ls) or ("past due" in ls)

    def is_overdue_alert_dict(d):
        if not isinstance(d, dict):
            return False
        for key in ["type", "alert_type", "category", "name", "title", "message", "description", "reason", "code", "tag"]:
            if str_contains_overdue(d.get(key)):
                return True
        return False

    def entry_associated_with_wheelchair(entry):
        # Association with loan LN-500a3 or equipment EQ-100
        if isinstance(entry, dict):
            ids = []
            for k in ["loan_id", "related_loan_id", "reference_loan_id", "entity_id", "id"]:
                v = entry.get(k)
                if isinstance(v, str):
                    ids.append(v)
            if "LN-500a3" in ids:
                return True
            if entry.get("equipment_id") == "EQ-100":
                return True
            ref = entry.get("reference")
            if isinstance(ref, str) and ("LN-500a3" in ref or "EQ-100" in ref):
                return True
            return False
        elif isinstance(entry, str):
            # String entries: require mention of IDs to associate
            return ("LN-500a3" in entry) or ("EQ-100" in entry)
        return False

    def check_container_for_overdue_alert(container):
        # Returns True if an overdue alert associated with LN-500a3/EQ-100 is found
        if isinstance(container, dict):
            # The dict itself might be an alert
            if is_overdue_alert_dict(container) and entry_associated_with_wheelchair(container):
                return True
            for val in container.values():
                if isinstance(val, dict):
                    if is_overdue_alert_dict(val) and entry_associated_with_wheelchair(val):
                        return True
                elif isinstance(val, list):
                    for item in val:
                        if isinstance(item, dict):
                            if is_overdue_alert_dict(item) and entry_associated_with_wheelchair(item):
                                return True
                        elif isinstance(item, str):
                            if str_contains_overdue(item) and entry_associated_with_wheelchair(item):
                                return True
                elif isinstance(val, str):
                    if str_contains_overdue(val) and entry_associated_with_wheelchair(val):
                        return True
        elif isinstance(container, list):
            for item in container:
                if isinstance(item, dict):
                    if is_overdue_alert_dict(item) and entry_associated_with_wheelchair(item):
                        return True
                elif isinstance(item, str):
                    if str_contains_overdue(item) and entry_associated_with_wheelchair(item):
                        return True
        elif isinstance(container, str):
            if str_contains_overdue(container) and entry_associated_with_wheelchair(container):
                return True
        return False

    try:
        loans = final_state.get("loans", {})
        ln = loans.get("LN-500a3")
        if not isinstance(ln, dict):
            return False

        due_str = ln.get("due_date")
        ret_str = ln.get("returned_date")
        due_date = parse_due_date(due_str)
        returned_dt = parse_returned_datetime(ret_str)
        if due_date is None or returned_dt is None:
            return False

        past_due = returned_dt.date() > due_date
        if not past_due:
            # Condition not applicable; requirement is satisfied
            return True

        # Check for overdue alert within the loan record itself
        if ln.get("overdue_alert") is True:
            return True
        for key in ["alert", "alerts", "flags", "notes", "note", "remark", "remarks"]:
            v = ln.get(key)
            if isinstance(v, str) and str_contains_overdue(v):
                return True
            elif isinstance(v, list):
                for item in v:
                    if isinstance(item, str) and str_contains_overdue(item):
                        return True
                    elif isinstance(item, dict) and is_overdue_alert_dict(item):
                        return True
            elif isinstance(v, dict):
                if is_overdue_alert_dict(v):
                    return True

        # Check top-level containers for alerts tied to this loan/equipment
        top_keys = ["alerts", "notifications", "events", "logs", "activity", "audit_log", "init_config"]
        for key in top_keys:
            container = final_state.get(key)
            if container is None:
                continue
            if key == "init_config" and isinstance(container, dict):
                # Check init_config itself and any nested alert-like subcontainers
                if check_container_for_overdue_alert(container):
                    return True
                for subkey in ["alerts", "notifications", "events", "logs"]:
                    subcont = container.get(subkey)
                    if subcont is not None and check_container_for_overdue_alert(subcont):
                        return True
            else:
                if check_container_for_overdue_alert(container):
                    return True

        # Check equipment record for embedded alert info
        eq = final_state.get("equipment", {}).get("EQ-100")
        if isinstance(eq, dict):
            for key in ["alert", "alerts", "flags", "notes", "note", "remark", "remarks"]:
